#include <iostream>
#include <vector>
#include <cassert>
using namespace std;

struct Matrix {
    int h, w;
    vector<long long> a;
    Matrix(int n=0):h(n),w(n),a(n*n){}
    Matrix(int n, int m):h(n),w(m),a(n*m){}
    long long& get(int r,int c){return a[r*w+c];}
    long long get(int r,int c)const{return a[r*w+c];}
    Matrix& operator+=(const Matrix& m){
        assert(h==m.h && w==m.w);
        for(int i=0;i<h*w;++i)a[i]+=m.a[i];
        return *this;
    }
    Matrix& operator-=(const Matrix& m){
        assert(h==m.h && w==m.w);
        for(int i=0;i<h*w;++i)a[i]-=m.a[i];
        return *this;
    }
    Matrix& operator*=(const Matrix& m){
        assert(w==m.h);
        Matrix ret(h,m.w);
        for(int i=0;i<h;++i){
            for(int j=0;j<m.w;++j){
                for(int k=0;k<w;++k){
                    ret.a[i*m.w+j]+=a[i*w+k]*m.a[k*m.w+j]%mod;
                }
                ret.a[i*m.w+j]%=mod;
            }
        }
        *this=ret;
        return *this;
    }
    Matrix operator+(const Matrix& m)const{return Matrix(*this)+=m;}
    Matrix operator-(const Matrix& m)const{return Matrix(*this)-=m;}
    Matrix operator*(const Matrix& m)const{return Matrix(*this)*=m;}
};

template<typename T>
Matrix<T> identity(int n){
    Matrix<T> ret(n);
    for(int i=0;i<n;++i)ret.get(i,i)=1;
    return ret;
}

template<typename T>
Matrix<T> power(Matrix<T> a,int n){
    assert(a.h==a.w);
    Matrix<T> ret=identity<T>(a.h);
    while(n){
        if(n&1)ret*=a;
        a*=a;
        n>>=1;
    }
    return ret;
}

vector<Matrix<ll>> matrices(65);
ll compute(int i,int k){
    return power(matrices[i+k],k-i)*power(matrices[i],i);
}

ll solve(ll n,ll k){
    ll count=0,tmp=n;
    while(tmp){tmp/=k;++count;}
    vector<Matrix<ll>> b(count+5),c(count+5),d(k+1);
    b[0]=matrices[k-1];
    c[0]=power(b[0],k-1);
    b[1]=compute(k-1,k);
    c[1]=power(b[1],k-1);
    Matrix<ll> s=identity<ll>(2*k+1);
    for(int j=2;j<=count+1;++j){
        b[j]=compute(k-j%k,k);
        s*=c[j-1];
        b[j]*=s;
        c[j]=power(b[j],k-1);
    }
    int idx=1,rem=n%k;
    n-=rem;
    int q=0;
    tmp=n;
    if(tmp){while(tmp%k==0){++q;tmp/=k;}}
    q=(k-q%k)%k;
    Matrix<ll> ans=identity<ll>(2*k+1);
    ans=power(matrices[q],rem)*power(matrices[q+k],max(rem-q,0));
    n/=k;
    if(n==0){return (ans.get(2*k,0)+ans.get(0,0))%mod;}
    --n;
    while(n){
        int t=n%k;
        if(t){ans*=power(b[idx],t);}
        n/=k;++idx;
    }
    ans*=b[1];
    return (ans.get(2*k,0)+ans.get(0,0))%mod;
}

int main(){
    long long n,k;
    cin>>n>>k;
    for(int i=0;i<=2*k;++i){
        matrices[i]=Matrix<ll>(2*k+1);
        for(int j=0;j<i;++j)matrices[i].get(0,j)=1;
        for(int j=0;j<2*k-1;++j)matrices[i].get(j+1,j)=1;
        matrices[i].get(2*k,0)=1;
        matrices[i].get(2*k,2*k)=1;
    }
    cout<<solve(n,k)<<endl;
    return 0;
}
